alter table public.guardian_delivery_logs add column if not exists next_attempt_at timestamptz, add column if not exists processing_started_at timestamptz, add column if not exists provider_delivery_status text;
create index if not exists guardian_delivery_due_sms_idx on public.guardian_delivery_logs(next_attempt_at,created_at) where channel='sms' and status='queued';
create index if not exists guardian_delivery_stale_processing_idx on public.guardian_delivery_logs(processing_started_at) where channel='sms' and status='processing';
create or replace function public.claim_coachingos_guardian_deliveries(_institute_id uuid,_attendance_record_id uuid) returns setof public.guardian_delivery_logs language plpgsql security definer set search_path='' as $function$ begin return query update public.guardian_delivery_logs l set status='processing',attempt_count=l.attempt_count+1,processing_started_at=pg_catalog.now(),updated_at=pg_catalog.now() where l.institute_id=_institute_id and l.attendance_record_id=_attendance_record_id and l.channel='sms' and l.status='queued' and l.attempt_count<3 and (l.next_attempt_at is null or l.next_attempt_at<=pg_catalog.now()) returning l.*; end; $function$;
create or replace function public.claim_due_coachingos_guardian_sms(_batch_size integer default 50) returns setof public.guardian_delivery_logs language plpgsql security definer set search_path='' as $function$ begin if _batch_size<1 or _batch_size>200 then raise exception 'batch_size must be between 1 and 200'; end if; update public.guardian_delivery_logs l set status=case when l.attempt_count>=3 then 'failed' else 'queued' end,next_attempt_at=case when l.attempt_count>=3 then null else pg_catalog.now()+interval '2 minutes' end,processing_started_at=null,error_message='processing_lease_expired',updated_at=pg_catalog.now() where l.channel='sms' and l.status='processing' and l.processing_started_at<pg_catalog.now()-interval '10 minutes'; return query with due as (select l.id from public.guardian_delivery_logs l where l.channel='sms' and l.status='queued' and l.attempt_count<3 and (l.next_attempt_at is null or l.next_attempt_at<=pg_catalog.now()) order by coalesce(l.next_attempt_at,l.created_at),l.created_at for update skip locked limit _batch_size) update public.guardian_delivery_logs l set status='processing',attempt_count=l.attempt_count+1,processing_started_at=pg_catalog.now(),updated_at=pg_catalog.now() from due where l.id=due.id returning l.*; end; $function$;
create or replace function public.retry_coachingos_guardian_delivery(_log_id uuid) returns uuid language plpgsql security definer set search_path='' as $function$ declare target_institute uuid; target_attendance uuid; caller_role text; begin select l.institute_id into target_institute from public.guardian_delivery_logs l where l.id=_log_id and l.channel='sms'; if target_institute is null then raise exception 'SMS delivery log not found'; end if; select m.role into caller_role from public.institute_members m where m.institute_id=target_institute and m.user_id=(select auth.uid()) limit 1; if coalesce(caller_role,'') not in ('owner','admin','manager','receptionist') then raise exception 'Not authorized to retry guardian delivery' using errcode='42501'; end if; update public.guardian_delivery_logs l set status='queued',next_attempt_at=pg_catalog.now(),processing_started_at=null,error_message=null,updated_at=pg_catalog.now() where l.id=_log_id and l.channel='sms' and l.status in ('failed','blocked') and l.attempt_count<3 returning l.attendance_record_id into target_attendance; if target_attendance is null then raise exception 'SMS delivery is not retryable or retry limit reached'; end if; return target_attendance; end; $function$;
revoke all on function public.claim_due_coachingos_guardian_sms(integer) from public,anon,authenticated; grant execute on function public.claim_due_coachingos_guardian_sms(integer) to service_role;
revoke all on function public.claim_coachingos_guardian_deliveries(uuid,uuid) from public,anon,authenticated; grant execute on function public.claim_coachingos_guardian_deliveries(uuid,uuid) to service_role;
revoke all on function public.enqueue_guardian_attendance_delivery() from public,anon,authenticated;
revoke all on function public.retry_coachingos_guardian_delivery(uuid) from public,anon; grant execute on function public.retry_coachingos_guardian_delivery(uuid) to authenticated;